1	#!/usr/bin/env node
2	import { readFileSync } from 'node:fs';
3	import process from 'node:process';
4	
5	const forbidden = new Set(['gap', 'row-gap', 'column-gap', 'float', 'filter', 'backdrop-filter', 'background', 'background-image', 'box-shadow', 'outline', 'text-overflow', 'white-space', 'word-break', 'transition', 'animation']);
6	const bem = /^\.[a-z][a-z0-9]*(?:-[a-z0-9]+)*(?:__(?:[a-z0-9]+(?:-[a-z0-9]+)*))?(?:--[a-z0-9]+(?:-[a-z0-9]+)*)?$/;
7	
8	function issue(file, line, rule, message) { return `${file}:${line} [${rule}] ${message}`; }
9	function validate(file) {
10	  const errors = [];
11	  const lines = readFileSync(file, 'utf8').split(/\r?\n/);
12	  let depth = 0;
13	  for (let index = 0; index < lines.length; index += 1) {
14	    const line = lines[index].trim();
15	    const number = index + 1;
16	    const selector = line.match(/^(.+?)\s*\{$/);
17	    if (selector) {
18	      if (depth > 0) errors.push(issue(file, number, 'top-level-single-selector', '公共 Less 不允许嵌套规则'));
19	      if (!bem.test(selector[1].trim())) errors.push(issue(file, number, 'bem-selector', '选择器必须是单个 BEM 类'));
20	      depth += 1;
21	      continue;
22	    }
23	    if (line === '}') { depth -= 1; if (depth < 0) errors.push(issue(file, number, 'syntax', '存在未匹配的 }')); continue; }
24	    const declaration = line.match(/^([a-z-]+)\s*:\s*([^;]+);?$/i);
25	    if (!declaration) continue;
26	    const property = declaration[1].toLowerCase();
27	    const value = declaration[2].trim();
28	    if (forbidden.has(property)) errors.push(issue(file, number, 'forbidden-property', `${property} 不允许用于公共 Less`));
29	    if (property === 'line-height' && !/^-?\d+(?:\.\d+)?px$/i.test(value)) errors.push(issue(file, number, 'line-height-px', 'line-height 必须为 px 数值'));
30	    if (/\b(?:calc|var)\s*\(/.test(value) || /\b\d+(?:\.\d+)?(?:vh|vw|em|rem|rpx)\b/.test(value)) errors.push(issue(file, number, 'forbidden-unit', '公共 Less 不允许该单位或函数'));
31	  }
32	  if (depth !== 0) errors.push(issue(file, lines.length, 'syntax', '规则括号不匹配'));
33	  return errors;
34	}
35	const files = process.argv.slice(2);
36	if (files.length === 0) { console.error('[file] 必须提供 Less 文件'); process.exit(1); }
37	const errors = files.flatMap(validate);
38	if (errors.length) { console.error(errors.join('\n')); process.exit(1); }
39	console.log(`PASS ${files.length} 个 Less 文件`);
